    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12,
}

# Priority 1 (most specific) to priority 4 (least specific)
PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

# Match numbers like 12.34, 1,234.56, 100. 62 (OCR noise with space after dot)
NUMBER_RE = re.compile(r"(\d{1,3}(?:,\d{3})*|\d+)\.\s?(\d{2})(?!\d)")


def preprocess(img, mode="auto"):
    gray = img.convert("L")
    if mode == "auto":
        return ImageOps.autocontrast(gray, cutoff=2)
    if mode == "auto5":
        return ImageOps.autocontrast(gray, cutoff=5)
    if mode == "binary":
        return gray.point(lambda p: 255 if p > 128 else 0)
    if mode == "downscale_dilate":
        # For faded receipts: downscale and apply min filter to thicken strokes
        w, h = gray.size
        gray = gray.resize((w // 2, h // 2), Image.LANCZOS)
        gray = ImageOps.autocontrast(gray, cutoff=5)
        return gray.filter(ImageFilter.MinFilter(3))
    return gray


def ocr_image(img, psm=6, mode="auto"):
    processed = preprocess(img, mode)
    return pytesseract.image_to_string(processed, config=f"--psm {psm}")


def extract_number(text):
    """Return the last number (as float, as string with 2 decimals) found in text, or None."""
    matches = list(NUMBER_RE.finditer(text))
    if not matches:
        return None
    m = matches[-1]
    integer_part = m.group(1).replace(",", "")
    decimal_part = m.group(2)
    return f"{integer_part}.{decimal_part}"


def has_keyword(line_upper, keywords):
    return any(kw in line_upper for kw in keywords)


def has_exclusion(line_upper):
    return any(kw in line_upper for kw in EXCLUSION_KEYWORDS)


def find_total(text):
    """Find total amount using priority keyword matching with exclusion."""
    lines = text.split("\n")
    uppers = [l.upper() for l in lines]

    for priority_idx, keywords in enumerate(PRIORITY_KEYWORDS):
        apply_exclusion = (priority_idx == 3)  # Apply exclusion only for generic keywords
        for i, line_upper in enumerate(uppers):
            if not has_keyword(line_upper, keywords):
                continue
            if apply_exclusion and has_exclusion(line_upper):
                continue
            # Try to extract number from this line
            num = extract_number(lines[i])
            if num is not None:
                return num
            # Fallback: use last number on next line
            if i + 1 < len(lines):
                num = extract_number(lines[i + 1])
                if num is not None:
                    return num
    return None


def parse_date(text):
    """Find and parse a date from text, return ISO format YYYY-MM-DD or None."""
    # Pattern 1: DD/MM/YYYY, DD-MM-YYYY, D/M/YYYY, DD/MM/YY etc.
    # Match: day (1-31) sep month (1-12) sep year (2 or 4 digits)
    patterns = [
        # dd/mm/yyyy or dd-mm-yyyy
        re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})\b"),
        # dd Mon yyyy, e.g., 28 Mar 2018 or 28 Mar 18
        re.compile(r"\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{2,4})\b"),
    ]

    for pat in patterns:
        for match in pat.finditer(text):
            g = match.groups()
            try:
                day = int(g[0])
                if g[1].isdigit():
                    month = int(g[1])
                else:
                    key = g[1].lower().strip(".")
                    if key not in MONTHS:
                        continue
                    month = MONTHS[key]
                year = int(g[2])
                if year < 100:
                    year += 2000
                if not (1 <= day <= 31 and 1 <= month <= 12 and 2000 <= year <= 2099):
                    continue
                return f"{year:04d}-{month:02d}-{day:02d}"
            except (ValueError, KeyError):
                continue
    return None


def ocr_all_variants(img):
    """Run OCR with multiple PSM/preprocessing variants and return combined texts."""
    variants = []
    for psm in [6, 4, 3, 11]:
        for mode in ["auto", "auto5"]:
            try:
                text = ocr_image(img, psm=psm, mode=mode)
                variants.append(text)
            except Exception:
                pass
    # Faded receipt fallback
    try:
        variants.append(ocr_image(img, psm=6, mode="downscale_dilate"))
    except Exception:
        pass
    return variants


def process_image(path):
    img = Image.open(path)
    texts = ocr_all_variants(img)

    # Try each variant to find a valid total and date
    total = None
    date = None
    for text in texts:
        if total is None:
            total = find_total(text)
        if date is None:
            date = parse_date(text)
        if total and date:
            break
    return date, total


def main():
    results = []
    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = os.path.join(IMG_DIR, fname)
        date, total = process_image(path)
        print(f"{fname}: date={date}, total={total}")
        results.append((fname, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname, date, total in results:
        ws.append([fname, date, total])
    wb.save(OUT_FILE)
    print(f"\nSaved to {OUT_FILE}")


if __name__ == "__main__":
    main()
