from collections import Counter

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageOps, ImageFilter

IMG_DIR = "/app/workspace/dataset/img"
OUT_FILE = "/app/workspace/stat_ocr.xlsx"

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6,
    "july": 7, "august": 8, "september": 9, "october": 10, "november": 11, "december": 12,
}

# Priority 1 (most specific) to priority 4 (least specific)
# Within each priority, keywords are matched in order
PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["AMOUNT DUE", "TOTAL DUE", "BALANCE DUE",
     "NETT TOTAL", "NET TOTAL",
     "AMT DUE", "AMT. DUE",
     "TOTAL", "AMOUNT"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

# Match X.XX, X,XXX.XX, allowing optional space after dot and extra OCR noise digit
NUMBER_RE = re.compile(r"(\d{1,3}(?:,\d{3})*|\d+)\.\s?(\d{2})(?!\d{2,})")


def preprocess(img, mode):
    gray = img.convert("L")
    if mode == "auto":
        return ImageOps.autocontrast(gray, cutoff=2)
    if mode == "auto5":
        return ImageOps.autocontrast(gray, cutoff=5)
    if mode == "downscale":
        # For faded receipts
        w, h = gray.size
        gray = gray.resize((w // 2, h // 2), Image.LANCZOS)
        gray = ImageOps.autocontrast(gray, cutoff=5)
        return gray.filter(ImageFilter.MinFilter(3))
    return gray


def ocr_text(img, psm, mode):
    processed = preprocess(img, mode)
    return pytesseract.image_to_string(processed, config=f"--psm {psm}")


def extract_last_number(text):
    """Return the last valid currency number as 'X.XX' string, or None."""
    matches = list(NUMBER_RE.finditer(text))
    if not matches:
        return None
    m = matches[-1]
    integer_part = m.group(1).replace(",", "")
    decimal_part = m.group(2)
    return f"{integer_part}.{decimal_part}"


def normalize_for_match(line):
    """Normalize line for keyword matching: uppercase, strip and collapse spaces/hyphens."""
    return re.sub(r"[\s\-]+", " ", line.upper()).strip()


def contains_any(normalized_line, keywords):
    return any(kw in normalized_line for kw in keywords)


def is_excluded(normalized_line):
    """Check if a normalized line contains exclusion keywords."""
    norm_exclusions = [re.sub(r"[\s\-]+", " ", kw) for kw in EXCLUSION_KEYWORDS]
    return any(kw in normalized_line for kw in norm_exclusions)


def find_total(text):
    """Find total amount using priority keyword matching with exclusion."""
    lines = text.split("\n")
    norm_lines = [normalize_for_match(l) for l in lines]

    for priority_idx, keywords in enumerate(PRIORITY_KEYWORDS):
        norm_keywords = [re.sub(r"[\s\-]+", " ", kw.upper()) for kw in keywords]
        apply_exclusion = (priority_idx >= 1)  # Apply exclusion to all except GRAND TOTAL
        for i, nl in enumerate(norm_lines):
            if not contains_any(nl, norm_keywords):
                continue
            if apply_exclusion and is_excluded(nl):
                continue
            num = extract_last_number(lines[i])
            if num is not None:
                return num
            # Fallback: next line
            if i + 1 < len(lines):
                num = extract_last_number(lines[i + 1])
                if num is not None:
                    return num
    return None


def parse_date(text):
    """Find and parse a date, return YYYY-MM-DD or None."""
    patterns = [
        re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})\b"),
        re.compile(r"\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{2,4})\b"),
    ]
    for pat in patterns:
        for match in pat.finditer(text):
            g = match.groups()
            try:
                day = int(g[0])
                if g[1].isdigit():
                    month = int(g[1])
                else:
                    key = g[1].lower().strip(".")
                    if key not in MONTHS:
                        continue
                    month = MONTHS[key]
                year = int(g[2])
                if year < 100:
                    year += 2000
                if not (1 <= day <= 31 and 1 <= month <= 12 and 2000 <= year <= 2099):
                    continue
                return f"{year:04d}-{month:02d}-{day:02d}"
            except (ValueError, KeyError):
                continue
    return None


def pick_most_common(candidates):
    """From a list of candidates (possibly with None), pick the most common non-None value."""
    non_none = [c for c in candidates if c is not None]
    if not non_none:
        return None
    counter = Counter(non_none)
    return counter.most_common(1)[0][0]


def process_image(path):
    img = Image.open(path)
    # OCR variants: (psm, mode)
    variants = [
        (6, "auto"), (6, "auto5"),
        (4, "auto"), (4, "auto5"),
        (3, "auto"), (3, "auto5"),
        (6, "downscale"),
    ]
    dates = []
    totals = []
    for psm, mode in variants:
        try:
            text = ocr_text(img, psm, mode)
        except Exception:
            continue
        dates.append(parse_date(text))
        totals.append(find_total(text))

    return pick_most_common(dates), pick_most_common(totals)


def main():
    results = []
    for fname in sorted(os.listdir(IMG_DIR)):
        if not fname.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = os.path.join(IMG_DIR, fname)
        date, total = process_image(path)
        print(f"{fname}: date={date}, total={total}")
        results.append((fname, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname, date, total in results:
        ws.append([fname, date, total])
    wb.save(OUT_FILE)
    print(f"\nSaved to {OUT_FILE}")


if __name__ == "__main__":
    main()
